var engine = OcrEngine.TryCreateFromLanguage(selectedLanguage);
if (engine is null)
{
    return OcrAttempt.Unavailable(selectedLanguage.LanguageTag);
}

try
{
    return OcrAttempt.Success(await engine.RecognizeAsync(softwareBitmap));
}
catch (Exception ex) when (IsPlatformOcrFailure(ex))
{
    return OcrAttempt.Failed(selectedLanguage.LanguageTag, ex.HResult);
}
